mapper.select:
select po_id, po_no, rev, status, source, cust_id, plant_cd, wh_id, po_date
  from srm_po where po_id = #{poId}
   for update

mapper.update:
update srm_asn
   set status = #{to}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where asn_id = #{asnId} and status = #{from}

update srm_po_line
   set recv_qty = recv_qty + #{qty}, updated_at = now(), updated_by = #{by}
 where po_line_id = #{poLineId}

mapper.select:
select coalesce(bool_or(l.recv_qty > 0), false) as any_recv,
       coalesce(bool_and(l.recv_qty >= l.qty - l.cancel_qty) filter (where l.line_status = 'OPEN' and l.qty - l.cancel_qty > 0), false) as full
  from srm_po_line l where l.po_id = #{poId}

mapper.update:
update srm_po
   set status = #{to}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where po_id = #{poId} and status = #{from}
